shell_commands:
/bin/zsh -lc "cat > scripts/lore-descriptors.test.ts <<'EOF'
import {descriptor} from './lore-descriptors.mjs';

// specs/lore-test-descriptors/spec.md#1
it('includes a stamped spec anchor in the test descriptor', () => {
  const source = \"// specs/example/spec.md#2\\nit('works', () => {});\\n\";

  expect(descriptor('src/example.test.ts', {fullName: 'works', location: {line: 2}}, source)).toEqual({
    id: 'src/example.test.ts::works',
    name: 'works',
    file: 'src/example.test.ts',
    spec: 'specs/example/spec.md#2',
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath scripts/lore-descriptors.test.ts"
